import urllib.request,urllib.error,json
base='https://app.ontrackegy.com'
cases=[('/login','تسجيل الدخول'),('/register','إنشاء حساب'),('/forgot-password','نسيت كلمة المرور'),('/portal/delta-voice/login','SOG'),('/portal/delta-voice/register','SOG'),('/portal/nile-voice/login','نيل فويس'),('/assets/css/app.css','2026-11-05 responsive structural repairs'),('/assets/js/app.js','nav-open')]
out=[]
for route,expected in cases:
 try:
  with urllib.request.urlopen(urllib.request.Request(base+route,headers={'User-Agent':'OnTrackResponsiveReleaseCheck/1.0'}),timeout=6) as r:
   text=r.read(150000).decode('utf-8','replace')
   out.append({'route':route,'status':r.status,'expected':expected in text})
 except urllib.error.HTTPError as e:out.append({'route':route,'status':e.code,'expected':False})
 except Exception as e:out.append({'route':route,'error':type(e).__name__,'expected':False})
print(json.dumps({'pages':out,'all_pass':all(x.get('status')==200 and x['expected'] for x in out)},ensure_ascii=False))
